import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Conditions d'utilisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/terms.md","filePath":"fr/guide/terms.md","lastUpdated":1793173149000}`),a={name:`fr/guide/terms.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="conditions-d-utilisation" tabindex="-1">Conditions d&#39;utilisation <a class="header-anchor" href="#conditions-d-utilisation" aria-label="Permalink to “Conditions d&#39;utilisation”">​</a></h1><p>Les présentes Conditions régissent votre utilisation de l&#39;application Sudoku. En téléchargeant, en installant ou en utilisant Sudoku, vous acceptez ces Conditions. Si vous ne les acceptez pas, n&#39;utilisez pas l&#39;application.</p><h2 id="licence-et-utilisation" tabindex="-1">Licence et utilisation <a class="header-anchor" href="#licence-et-utilisation" aria-label="Permalink to “Licence et utilisation”">​</a></h2><p>Sudoku est fourni selon les conditions de licence incluses avec chaque version. Une licence limitée, non exclusive et non transférable vous est accordée pour utiliser l&#39;application sur vos appareils, conformément aux conditions de licence.</p><h2 id="une-conception-hors-ligne-avec-des-fonctions-cloud-facultatives" tabindex="-1">Une conception hors ligne, avec des fonctions cloud facultatives <a class="header-anchor" href="#une-conception-hors-ligne-avec-des-fonctions-cloud-facultatives" aria-label="Permalink to “Une conception hors ligne, avec des fonctions cloud facultatives”">​</a></h2><p>Sudoku est une application conçue hors ligne en priorité. Toutes les données de jeu — réglages, état de la partie et statistiques — sont stockées localement sur votre appareil par défaut.</p><p>Les fonctions cloud facultatives comprennent :</p><ul><li><strong>Synchronisation iCloud</strong> (via CloudKit) : synchronise les données entre vos appareils Apple à l&#39;aide de votre compte iCloud personnel.</li><li><strong>Game Center</strong> : fournit des classements et des succès.</li><li><strong>« Plus d&#39;apps »</strong> : une fonction facultative qui récupère une liste d&#39;applications de la même famille ; aucune donnée personnelle n&#39;est transmise.</li></ul><p>Aucune donnée personnelle n&#39;est collectée par nos soins au-delà de ce qui est géré par les services iCloud et Game Center d&#39;Apple lorsque vous y consentez explicitement.</p><h2 id="responsabilites-de-l-utilisateur" tabindex="-1">Responsabilités de l&#39;utilisateur <a class="header-anchor" href="#responsabilites-de-l-utilisateur" aria-label="Permalink to “Responsabilités de l&#39;utilisateur”">​</a></h2><ul><li>Utiliser Sudoku de manière licite et conformément aux règles applicables.</li><li>Ne pas tenter de décompiler, de désosser ou de modifier l&#39;application en violation de la licence.</li><li>Ne pas utiliser l&#39;application à des fins illégales.</li></ul><h2 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to “Confidentialité”">​</a></h2><p>Veuillez consulter la Politique de confidentialité pour en savoir plus sur nos pratiques en matière de données. En bref : aucune donnée n&#39;est collectée par nos soins ; les fonctions cloud facultatives reposent uniquement sur les services iCloud et Game Center d&#39;Apple, avec votre consentement explicite.</p><h2 id="absence-de-garantie" tabindex="-1">Absence de garantie <a class="header-anchor" href="#absence-de-garantie" aria-label="Permalink to “Absence de garantie”">​</a></h2><p>Sudoku est fourni « en l&#39;état », sans garantie d&#39;aucune sorte. Dans toute la mesure permise par la loi, les mainteneurs déclinent toute garantie, expresse, implicite, légale ou autre, y compris la qualité marchande et l&#39;adéquation à un usage particulier.</p><h2 id="limitation-de-responsabilite" tabindex="-1">Limitation de responsabilité <a class="header-anchor" href="#limitation-de-responsabilite" aria-label="Permalink to “Limitation de responsabilité”">​</a></h2><p>Dans toute la mesure permise par la loi, les mainteneurs ne sauraient être tenus responsables des dommages indirects, accessoires, spéciaux, consécutifs ou exemplaires résultant de votre utilisation de l&#39;application.</p><h2 id="resiliation" tabindex="-1">Résiliation <a class="header-anchor" href="#resiliation" aria-label="Permalink to “Résiliation”">​</a></h2><p>Les droits qui vous sont accordés prennent fin automatiquement si vous ne respectez pas les présentes Conditions.</p><h2 id="modifications" tabindex="-1">Modifications <a class="header-anchor" href="#modifications" aria-label="Permalink to “Modifications”">​</a></h2><p>Nous pouvons mettre à jour ces Conditions de temps à autre. La poursuite de l&#39;utilisation après modification vaut acceptation des Conditions révisées.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>Pour toute question relative aux présentes Conditions, ouvrez une issue sur le dépôt du projet : <code>https://github.com/sudoku-pro/sudoku-site/issues</code>.</p><p><em>Dernière mise à jour : 2026-07-29</em></p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};